otes":"착용 이력이 있는 중고 상품입니다.\n8/10 · 상급\n분류 · 빈티지\n연식에 따른 자연스러운 변화가 있으나 전체적으로 균형 있게 관리된 컨디션입니다.","is_vintage":true},{"product_no":"CAR-N21267-2","condition":"중고 7/10 · 양호","condition_notes":"착용 이력이 있는 중고 상품입니다.\n7/10 · 양호\n자연스러운 사용 이력이 일부 있으나 전반적으로 단정하게 관리된 컨디션입니다.","is_vintage":false},{"product_no":"ROL-N31265-4","condition":"중고 8/10 · 상급","condition_notes":"착용 이력이 있는 중고 상품입니다.\n8/10 · 상급\n전체적으로 깔끔하고 균형 있게 관리된 컨디션입니다.","is_vintage":false}]$bellore$::jsonb) as x(
    product_no text, condition text, condition_notes text, is_vintage boolean
  )
), updated as (
  update public.listings l
  set condition = c.condition,
      condition_notes = c.condition_notes,
      tags = case when c.is_vintage
        then array_append(array_remove(coalesce(l.tags, '{}'::text[]), 'vintage'), 'vintage')
        else array_remove(coalesce(l.tags, '{}'::text[]), 'vintage') end,
      updated_at = now()
  from changes c
  where l.product_no = c.product_no
  returning l.product_no, l.condition, l.condition_notes, l.tags
)
select count(*) as updated,
  count(*) filter (where condition like '%7/10%') as score7,
  count(*) filter (where condition like '%8/10%') as score8,
  count(*) filter (where condition like '%9/10%') as score9,
  count(*) filter (where 'vintage' = any(tags)) as vintage
from updated;

commit;
